// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address target) public {
        vm.assume(caller != address(this));
        vm.assume(target != address(0));
        vm.prank(address(this));
        c.deny(caller);

        vm.prank(caller);
        bool ok = true;
        try c.rely(target) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
